#!/bin/sh
# Thin build-and-run orchestration for the n131 pilot (no computation here).
#   ./run.sh OUTDIR [SMALL_CELLS] [K130_DIMS]
#   ./run.sh /tmp/n131-l5 5 ""          smallest cell (build, selfcheck, differential tests, l = 5)
# Builds n131.rs (rustc -O -C target-cpu=native) and summary.rs, runs selfcheck and the two
# differential tests (seeds 991, 992), then one process per target, one at a time, 600 s cap:
#   small: targets of the lin21 pilot (l = 5..12) and of the lin21-fast pilot (l = 13);
#   k130 : targets generated by `n131 k130targets --seed $KSEED` (8 uniform + 2 planted per d);
#          point-pair enumeration on every target for d <= 13, on idx 0 and 8 only for d >= 14.
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
OUT=${1:?usage: run.sh OUTDIR [SMALL_CELLS] [K130_DIMS]}
CELLS=${2-"5 6 7 8 9 10 11 12 13"}
DIMS=${3-"6 7 8 9 10 11 12 13 14"}
KSEED=${KSEED:-20261116}
T1=${TDIR:-"$HERE/../sat_native_lin21_20261116/raw"}   # override only for dry runs on other targets
T2="$HERE/../sat_native_lin21_fast_20261116/raw"
CAP=600
mkdir -p "$OUT/raw" "$OUT/bin"
rustc -O -C target-cpu=native -o "$OUT/bin/n131" "$HERE/n131.rs" 2>/dev/null
rustc -O -o "$OUT/bin/summary" "$HERE/summary.rs" 2>/dev/null
EXE="$OUT/bin/n131"
"$EXE" selfcheck > "$OUT/raw/selfcheck.jsonl"
"$EXE" dt --seed 991 --per 400 > "$OUT/raw/dt.jsonl"
"$EXE" dtmw --seed 992 --per 10 > "$OUT/raw/dtmw.jsonl"
date -u +%Y-%m-%dT%H:%M:%SZ >> "$OUT/raw/started_utc.txt"
for l in $CELLS; do
  T="$T1/targets_l$l.jsonl"; [ -f "$T" ] || T="$T2/targets_l$l.jsonl"
  sed -n 's/.*"idx":\([0-9]*\),.*"x_r":\([0-9]*\),.*/\1 \2/p' "$T" | while read -r idx xr; do
    lines=$(timeout "$CAP" "$EXE" small --l "$l" --xr "$xr" --idx "$idx") ||
      lines="{\"series\":\"small\",\"arm\":\"censored\",\"l\":$l,\"x_r\":$xr,\"status\":\"censored\"}"
    echo "$lines" >> "$OUT/raw/rows_small.jsonl"
  done
  echo "small l=$l done"
done
for d in $DIMS; do
  TF="$OUT/raw/k130_targets_d$d.jsonl"
  "$EXE" k130targets --d "$d" --seed "$KSEED" --uniform 8 --planted 2 > "$TF"
  sed -n 's/.*"idx":\([0-9]*\),"kind":"\([a-z]*\)",.*"x_r":"\([0-9a-f]*\)".*/\1 \2 \3/p' "$TF" | while read -r idx kind xr; do
    pairs=1; if [ "$d" -ge 14 ] && [ "$idx" -ne 0 ] && [ "$idx" -ne 8 ]; then pairs=0; fi
    lines=$(timeout "$CAP" "$EXE" k130 --d "$d" --xr "$xr" --idx "$idx" --kind "$kind" --pairs "$pairs") ||
      lines="{\"series\":\"k130\",\"arm\":\"censored\",\"d\":$d,\"x_r\":\"$xr\",\"kind\":\"$kind\",\"status\":\"censored\"}"
    echo "$lines" >> "$OUT/raw/rows_k130.jsonl"
  done
  echo "k130 d=$d done"
done
"$OUT/bin/summary" "$OUT" "$T1" "$T2" > /dev/null
echo "wrote $OUT/tables.md $OUT/results.json $OUT/fig_small_ratio_fastleaf.svg $OUT/fig_small_ratio_scan.svg $OUT/fig_k130_wall.svg"
